"""The latest benchmark report, generated by `python -m xss_detector evaluate` into reports/benchmark.json."""

from __future__ import annotations

import json

from app.core.repo import REPO_ROOT

BENCHMARK_PATH = REPO_ROOT / "reports" / "benchmark.json"  # tests point this elsewhere


class BenchmarkMissing(Exception):
    """The report has not been generated yet."""


class BenchmarkUnreadable(Exception):
    """The file exists but cannot be read or is not JSON."""


def load_benchmark() -> dict:
    try:
        raw = BENCHMARK_PATH.read_bytes()
    except FileNotFoundError as exc:
        raise BenchmarkMissing from exc
    except OSError as exc:
        raise BenchmarkUnreadable from exc
    try:
        data = json.loads(raw)
    except ValueError as exc:
        raise BenchmarkUnreadable from exc
    if not isinstance(data, dict):
        raise BenchmarkUnreadable
    return data
